const root=document.documentElement;const themeButton=document.querySelector("[data-theme-toggle]");const header=document.querySelector("[data-header]");const year=document.querySelector("[data-year]");const form=document.querySelector("[data-contact-form]");const storedTheme=localStorage.getItem("portfolio-theme");const preferredTheme=window.matchMedia("(prefers-color-scheme: light)").matches?"light":"dark";root.dataset.theme=storedTheme||preferredTheme;
function updateThemeLabel(){const nextTheme=root.dataset.theme==="dark"?"light":"dark";themeButton.setAttribute("aria-label",`Switch to ${nextTheme} theme`)}updateThemeLabel();themeButton.addEventListener("click",()=>{root.dataset.theme=root.dataset.theme==="dark"?"light":"dark";localStorage.setItem("portfolio-theme",root.dataset.theme);updateThemeLabel()});function updateHeader(){header.classList.toggle("scrolled",window.scrollY>24)}updateHeader();window.addEventListener("scroll",updateHeader,{passive:true});year.textContent=new Date().getFullYear();
const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add("visible");observer.unobserve(entry.target)}})},{threshold:.12});document.querySelectorAll(".reveal").forEach(element=>observer.observe(element));
const scriptURL="https://script.google.com/macros/s/AKfycbwaSRNaOcMI3zEIi92j91hWrh3gzFhzjq5hpzQPk2xTwF7xhkJJRZQaugg3mzvjvlL_/exec";form.addEventListener("submit",async event=>{event.preventDefault();const button=form.querySelector("button[type='submit']");const status=form.querySelector(".form-status");button.disabled=true;button.classList.add("loading");status.className="form-status";status.textContent="Sending your message…";try{await fetch(scriptURL,{method:"POST",body:new FormData(form),mode:"no-cors"});form.reset();status.className="form-status success";status.textContent="Message sent. Thanks—I’ll get back to you soon."}catch(error){status.className="form-status error";status.textContent="That didn’t send. Please try again or contact me through GitHub."}finally{button.disabled=false;button.classList.remove("loading")}});
